/**
 * Public study dataset: types and loaders.
 *
 * The JSON in `src/data` is generated by `scripts/build-content.mjs` from the
 * preserved archive. Nothing here invents content: every field traces to a
 * transcription, a board answer-key notice or the archived derived key.
 */
import papersData from '../data/papers.json' with { type: 'json' };
import keysData from '../data/keys.json' with { type: 'json' };
import syllabusData from '../data/syllabus.json' with { type: 'json' };
import { subjectLabels, type SubjectKey } from './subjects.ts';

export type { SubjectKey };
export { subjectLabels };
export type Category = 'I' | 'II';

export type Option = { label: string; text: string };
/**
 * A reconstructed figure for a question whose stem points at a diagram.
 *
 * The asset is original line art redrawn from the values printed in the
 * official booklet. It is never the publisher's artwork, and it never makes
 * the question scoreable: ADR-0002 holds that a redraw does not verify an
 * item.
 */
export type FigureAsset = {
  id: string;
  /** File name of the authored asset inside the collection's figure folder. */
  svg: string;
  /** Published path of the asset, relative to the site root. */
  url: string;
  kind: string;
  status: string;
  fidelity: string;
  /** Short text equivalent, used as the image's alternative text. */
  alt: string;
  /** Long text equivalent, published beside the figure. */
  description: string;
  /** How the redraw differs from the official artwork. */
  deviations: string;
  /** Whether the figure's kind has been reviewed against the original page. */
  reviewed: boolean;
};
export type Question = {
  provisionalAid?: { state: string; answer: string | null; note: string; source: string };
  id: string;
  n: number;
  subject: string;
  subjectKey: SubjectKey;
  category: Category;
  marks: number;
  stem: string;
  options: Option[];
  figure: boolean;
  figureNote: string | null;
  /** The reconstructed figure for this item, when the collection has one. */
  figureAsset: FigureAsset | null;
  transcriptionNote: string | null;
  optionsComplete: boolean;
  scorable: boolean;
  /**
   * The board voided this question and the transcription reproduces it
   * completely, so the board's award of the marks to every candidate applies.
   */
  boardAwarded: boolean;
  holdReason: string | null;
  sourceLine: number;
  keyAnswer: string | null;
  voided: boolean;
  hasKey: boolean;
};
export type PaperSubject = {
  subject: string;
  subjectKey: SubjectKey;
  from: number;
  to: number;
  categories: { category: Category; from: number; to: number }[];
};
export type Paper = {
  id: string;
  year: number;
  title: string;
  label: string;
  pattern: 'modern' | 'legacy';
  durationMinutes: number;
  maxMarks: number;
  questionCount: number;
  instructions: string[];
  subjects: PaperSubject[];
  notes: string[];
  gaps: number[];
  questions: Question[];
  sourceFile: string;
  sourceSha256: string;
  hasKey: boolean;
  keyTier: 'official' | 'derived' | null;
  scoreableQuestions: number;
  scoreableMarks: number;
  /** Questions the board voided that the transcription reproduces fully. */
  boardAwardedQuestions: number;
  boardAwardedMarks: number;
  heldQuestions: number;
  voidedQuestions: number[];
  /** Everything the learner can sit: keyed questions plus board-awarded ones. */
  rehearsableQuestions: number;
  rehearsableMarks: number;
};

export type AnswerKey = {
  year: number;
  paperId: string;
  tier: 'official' | 'derived';
  documentRef: string | null;
  documentDate: string | null;
  sourceTable: string | null;
  provenance: string | null;
  hostedBy: string | null;
  tableSemantics: string | null;
  booklet: {
    mapping?: string | null;
    set?: string | null;
    setSymbol?: string | null;
    bookletNumber?: string | null;
    sourceFile?: string | null;
    determination?: string | null;
  } | null;
  hasPaper: boolean;
  usableForScoring: boolean;
  voided: number[];
  answers: Record<string, string>;
  tiers?: Record<string, string>;
  reasoning?: Record<string, string>;
  sourceFile: string;
};

export type SyllabusTopic = { id: string; code: string; name: string; detail: string };
export type Syllabus = {
  edition: string;
  bulletinDate: string;
  examDate: string;
  examDurationMinutes: number;
  pattern: {
    categoryI: { marks: number; negative: number };
    categoryII: { marks: number; negative: number };
    totalQuestions: number;
    totalMarks: number;
  };
  subjects: { id: SubjectKey; name: string; topics: SyllabusTopic[] }[];
  sourceFile: string;
  sourceSha256: string;
  patternTableFound: boolean;
};

export const papers = papersData.papers as unknown as Paper[];
export const keys = keysData.keys as unknown as AnswerKey[];
export const syllabus = syllabusData.syllabus as unknown as Syllabus;

export const paperById = new Map(papers.map((paper) => [paper.id, paper]));
export const paperByYear = new Map(papers.map((paper) => [paper.year, paper]));
export const keyByYear = new Map(keys.map((key) => [key.year, key]));

/**
 * The subject names live in their own module so a browser bundle can use
 * them without pulling in the corpus. They are re-exported here so existing
 * callers keep working.
 */

/** Papers whose items can actually be scored with a published key. */
export const scorablePapers = papers.filter((paper) => paper.scoreableQuestions > 0);

/** Highest-scoring paper available for a full-paper rehearsal. */
export const mockPaper = scorablePapers.find((paper) => paper.year === 2025) ?? scorablePapers[0];

/** Subject weights for the modern Paper I pattern, taken from the syllabus bulletin. */
export const subjectOrder: SubjectKey[] = ['mathematics', 'physics', 'chemistry', 'electrical'];

export function questionsOf(paper: Paper, filter?: { subjectKey?: SubjectKey; scorableOnly?: boolean }): Question[] {
  return paper.questions.filter((question) => {
    if (filter?.subjectKey && question.subjectKey !== filter.subjectKey) return false;
    if (filter?.scorableOnly && !question.scorable) return false;
    return true;
  });
}

/**
 * The questions a learner can actually sit in this paper.
 *
 * A keyed question is marked against the answer key. A question the board
 * voided is not held: the board published "W", so no option is keyed and the
 * marks go to every candidate. Both belong in a rehearsal of the paper, and
 * both carry marks into the total.
 */
export function rehearsableQuestions(paper: Paper, subjectKey?: SubjectKey): Question[] {
  return paper.questions.filter((question) => {
    if (subjectKey && question.subjectKey !== subjectKey) return false;
    return question.scorable || question.boardAwarded;
  });
}

export function keyFor(paper: Paper): AnswerKey | undefined {
  return keyByYear.get(paper.year);
}

/** The published answer for one question, as a list of option letters. */
export function answerLetters(paper: Paper, question: Question): string[] {
  const key = keyFor(paper);
  const answer = key?.answers[String(question.n)];
  if (!answer) return [];
  return answer.split('').filter((letter) => 'ABCD'.includes(letter));
}

/** Human label for a key tier, used wherever a key is shown to a learner. */
export function keyTierLabel(key: AnswerKey | undefined): string {
  if (!key) return 'No key published';
  if (key.tier === 'official') return 'Official WBJEEB key';
  return 'Derived answer key (not published by the board)';
}
